#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""One-way migration: move an SPQ project off Multi-Spec onto the native store.

SPQ used to store Cycle state in a `specs.<workstream>` slot with
`SYNAPTORY_ACTIVE_SPEC` as the workstream id. #303/#304/#305 gave SPQ its own
store and native `cycle_id` / `workstream_id`, so a project on the old layout
has to be moved once. Forward only: there is no reverse migration, because the
old layout cannot express a collision-safe Cycle identity.

SCOPE IS DELIBERATELY NARROW. This refuses any `build_mode` other than `spq`.
Multi-Spec is RETAINED for scrum and kanban -- `migrate_to_multispec.py` and
`/switch-spec` are untouched -- so a scrum project running three label-filtered
boards keeps working and is never asked to change.

Usage:
    python3 migrate_spq_native.py [--project-dir DIR] [--yes]
                                  [--adopt-orphan-receipts]
                                  [--force-overwrite]

What it does, all inside one lock:
    1. Snapshot `.synaptory/.orchestrator/` AND `.synaptory.yaml` to
       `.synaptory/.migrations/<stamp>-pre-spq-native.tar.gz`, taken BEFORE the
       lock so a stuck holder cannot cost you the backup.
    2. Allocate a `cycle_id` for the Cycle each workstream slot is running.
    3. Hoist every SPQ spec slot VERBATIM to
       `spq/cycles/<cycle-id>/workstreams/<ws>/execution-state.json`, which
       preserves each Work Unit's `mcp_consumed_receipts` anti-replay ledger,
       `pipeline_log` timestamps, `retries`, `rejection_feedback` and `dod`.
    4. Move `specs/<ws>/receipts/*`, routing the cycle-level pseudo-unit
       receipts (`CYCLE-N-*`, `SYNC-N-*`, `CHECKPOINT-N-*`, `ACCEPTANCE-N-*`)
       to the Cycle receipts dir and Work-Unit receipts to the workstream's.
    5. Move `specs/<ws>/tracker-data.json` alongside.
    6. Write `index.json`, the workstream pin, and rewrite
       `pipeline-state.json` as the mode + identity pointer.
    7. Record every file move to
       `.synaptory/.migrations/<stamp>-receipt-map.json`.

`.synaptory/sync/` is NOT touched: it is git-tracked, per-Cycle, and independent
of the state layout.

Re-running on an already-native project is a no-op (prints a diagnostic, exits
0). Collisions REFUSE rather than clobber, unless `--force-overwrite`.
"""

from __future__ import annotations

import argparse
import datetime as _dt
import json
import os
import re
import shutil
import sys
import tarfile
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def _resolve_lib_dir() -> Path:
    """Locate the shared lib/ directory.

    It sits at a different depth per layout (`core/lib` in the source tree,
    `<pkg>/hooks/lib` once composed, `<pkg>/runtime/../hooks/lib` on Codex), so
    probe rather than count parents. This is why the script works unchanged in
    all three host packages with no new build step.
    """
    here = Path(__file__).resolve().parent
    sys.path.insert(0, str(here))
    from _runtime_paths import find_lib_dir  # type: ignore

    return find_lib_dir(here)


HOOKS_LIB = _resolve_lib_dir()
sys.path.insert(0, str(HOOKS_LIB))

import spq_paths  # type: ignore  # noqa: E402
import state_store  # type: ignore  # noqa: E402

# Cycle-level pseudo Work Unit ids (`spq_state_machine.PSEUDO_STORY_IDS`). These
# belong to the Cycle, not to any one workstream.
_CYCLE_RECEIPT_RE = re.compile(
    r"^(CYCLE|SYNC|CHECKPOINT|ACCEPTANCE|DISCOVERY)-(\d+)(?:-|\.)"
)


class MigrationError(RuntimeError):
    """A refusal the operator must resolve; never a partial migration."""


def _utc_stamp() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _orch(project_dir: Path) -> Path:
    return project_dir / ".synaptory" / ".orchestrator"


def _state_path(project_dir: Path) -> Path:
    return _orch(project_dir) / "pipeline-state.json"


def _snapshot(project_dir: Path, stamp: str) -> Optional[Path]:
    """Tar the orchestrator dir AND the config, before taking any lock.

    The config is in scope because a future revision of this script may touch
    it; the predecessor only tarred `.orchestrator/` and that asymmetry is the
    kind of thing nobody notices until a rollback is needed.
    """
    orch = _orch(project_dir)
    if not orch.is_dir():
        return None
    migrations = project_dir / ".synaptory" / ".migrations"
    migrations.mkdir(parents=True, exist_ok=True)
    tar_path = migrations / ("%s-pre-spq-native.tar.gz" % stamp)
    with tarfile.open(tar_path, "w:gz") as tar:
        tar.add(orch, arcname=".orchestrator")
        config = project_dir / ".synaptory.yaml"
        if config.is_file():
            tar.add(config, arcname=".synaptory.yaml")
    return tar_path


def _classify_receipt(name: str) -> Tuple[str, Optional[int]]:
    """`("cycle", seq)` for a pseudo-unit receipt, else `("unit", None)`."""
    match = _CYCLE_RECEIPT_RE.match(name)
    if match:
        return "cycle", int(match.group(2))
    return "unit", None


def _move(src: Path, dst: Path, *, force: bool, moves: List[Dict[str, str]]) -> None:
    dst.parent.mkdir(parents=True, exist_ok=True)
    if dst.exists() and not force:
        raise MigrationError(
            "refusing to overwrite %s with %s. A stale file at the destination "
            "usually means a partial earlier run; inspect it, then re-run with "
            "--force-overwrite if the source is authoritative." % (dst, src)
        )
    shutil.move(str(src), str(dst))
    moves.append({"from": str(src), "to": str(dst)})


def plan(project_dir: Path) -> Dict[str, Any]:
    """Read the current state and describe what would move. Never writes."""
    full = state_store.read_json(str(_state_path(project_dir)))
    if not full:
        return {"status": "no_state"}

    mode = str(full.get("build_mode") or "unknown").lower()
    specs = full.get("specs")
    if not (full.get("version") == "3.0" and isinstance(specs, dict)):
        return {"status": "already_native", "build_mode": mode}

    if mode != "spq":
        raise MigrationError(
            "this project is build_mode %r, not spq. Multi-Spec is RETAINED for "
            "scrum and kanban (#303/#304/#305 scope the decoupling to SPQ), so "
            "there is nothing to migrate and nothing to change. If you meant to "
            "convert the project to SPQ, that is a lifecycle change, not a "
            "storage migration." % mode
        )

    workstreams = []
    for ws_id, slot in sorted(specs.items()):
        if not isinstance(slot, dict):
            continue
        workstreams.append(
            {
                "workstream_id": ws_id,
                "lifecycle_state": slot.get("lifecycle_state"),
                "current_cycle": int(slot.get("current_cycle") or 0),
                "work_units": len(slot.get("current_stories") or []),
                "receipts": len(
                    list((_orch(project_dir) / "specs" / ws_id / "receipts").glob("*.json"))
                )
                if (_orch(project_dir) / "specs" / ws_id / "receipts").is_dir()
                else 0,
            }
        )
    return {
        "status": "migratable",
        "build_mode": mode,
        "active_spec": full.get("active_spec"),
        "workstreams": workstreams,
    }


def migrate(
    project_dir: Path,
    *,
    adopt_orphan_receipts: bool = False,
    force_overwrite: bool = False,
) -> Dict[str, Any]:
    proposal = plan(project_dir)
    if proposal["status"] == "no_state":
        return {"status": "no_state", "message": "no pipeline state to migrate"}
    if proposal["status"] == "already_native":
        return {
            "status": "already_native",
            "message": "already on the native SPQ layout; nothing to do",
        }

    stamp = _utc_stamp()
    snapshot = _snapshot(project_dir, stamp)

    orch = _orch(project_dir)
    state_file = _state_path(project_dir)
    moves: List[Dict[str, str]] = []
    warnings: List[str] = []
    result_workstreams: List[Dict[str, Any]] = []

    with state_store.transaction(str(state_file) + ".lock"):
        full = state_store.read_json(str(state_file))
        specs = full.get("specs") or {}

        # One cycle_id per distinct Cycle number. Workstreams running the same N
        # are the same Cycle -- that is the whole premise of the barrier -- so
        # they must land under one identity or the quorum can never be assembled.
        cycle_ids: Dict[int, str] = {}
        for ws_id, slot in sorted(specs.items()):
            if not isinstance(slot, dict):
                continue
            seq = int(slot.get("current_cycle") or 0)
            if seq not in cycle_ids:
                cycle_ids[seq] = spq_paths.new_cycle_id(
                    seq,
                    goal=str(slot.get("cycle_goal") or ""),
                    created_at=stamp,
                    project_slug=project_dir.name,
                )

        primary_ws = full.get("active_spec") if isinstance(full.get("active_spec"), str) else None

        for ws_id, slot in sorted(specs.items()):
            if not isinstance(slot, dict):
                continue
            seq = int(slot.get("current_cycle") or 0)
            cycle_id = cycle_ids[seq]
            try:
                spq_paths.valid_workstream_id(ws_id)
            except spq_paths.IdentityError as exc:
                raise MigrationError(
                    "spec id %r cannot be used as a workstream id: %s. Rename it "
                    "in .synaptory.yaml first; a workstream id becomes a path "
                    "segment and a git ref component." % (ws_id, exc)
                )

            # Hoist the slot VERBATIM. Every field matters: dropping
            # `mcp_consumed_receipts` would silently re-arm consumed receipts
            # for replay, and dropping `pipeline_log` entered_at timestamps
            # would make every fresh receipt look stale.
            body = dict(slot)
            body.setdefault("version", "2.0")
            body["build_mode"] = "spq"
            body.pop("_spec_id", None)
            body.pop("_multispec", None)

            dest = Path(spq_paths.execution_state_path(str(project_dir), cycle_id, ws_id))
            if dest.exists() and not force_overwrite:
                raise MigrationError(
                    "refusing to overwrite existing native state at %s" % dest
                )
            dest.parent.mkdir(parents=True, exist_ok=True)
            state_store.write_json_atomic(str(dest), body)

            # Receipts, routed by id shape.
            src_receipts = orch / "specs" / ws_id / "receipts"
            moved_cycle = moved_unit = orphaned = 0
            if src_receipts.is_dir():
                for entry in sorted(src_receipts.iterdir()):
                    if not entry.is_file():
                        continue
                    kind, receipt_seq = _classify_receipt(entry.name)
                    if kind == "cycle":
                        target_cycle = cycle_ids.get(receipt_seq or seq)
                        if target_cycle is None:
                            if not adopt_orphan_receipts:
                                warnings.append(
                                    "left %s in place: it names Cycle %s, which "
                                    "no workstream slot is running. Re-run with "
                                    "--adopt-orphan-receipts to file it under "
                                    "the current Cycle."
                                    % (entry.name, receipt_seq)
                                )
                                orphaned += 1
                                continue
                            target_cycle = cycle_id
                        _move(
                            entry,
                            Path(
                                spq_paths.receipts_dir(
                                    str(project_dir), cycle_id=target_cycle
                                )
                            )
                            / entry.name,
                            force=force_overwrite,
                            moves=moves,
                        )
                        moved_cycle += 1
                    else:
                        _move(
                            entry,
                            Path(
                                spq_paths.receipts_dir(
                                    str(project_dir),
                                    cycle_id=cycle_id,
                                    workstream_id=ws_id,
                                )
                            )
                            / entry.name,
                            force=force_overwrite,
                            moves=moves,
                        )
                        moved_unit += 1

            tracker_data = orch / "specs" / ws_id / "tracker-data.json"
            if tracker_data.is_file():
                _move(
                    tracker_data,
                    Path(spq_paths.tracker_data_path(str(project_dir), cycle_id, ws_id)),
                    force=force_overwrite,
                    moves=moves,
                )

            spq_paths.record_cycle(
                str(project_dir),
                cycle_id,
                seq=seq,
                goal=str(slot.get("cycle_goal") or ""),
                opened_at=str(slot.get("started_at") or stamp),
                make_current=(ws_id == primary_ws) or (primary_ws is None),
            )

            result_workstreams.append(
                {
                    "workstream_id": ws_id,
                    "cycle_id": cycle_id,
                    "cycle_seq": seq,
                    "work_units": len(body.get("current_stories") or []),
                    "receipts_moved": {"cycle": moved_cycle, "work_unit": moved_unit},
                    "receipts_left_in_place": orphaned,
                }
            )

        # The pin names THIS checkout's workstream. With several slots there is
        # no single right answer, so pin only the unambiguous case and say so
        # otherwise: a wrong pin silently attributes one lane's work to another.
        if len(result_workstreams) == 1:
            spq_paths.write_pin(str(project_dir), result_workstreams[0]["workstream_id"])
        elif primary_ws:
            spq_paths.write_pin(str(project_dir), primary_ws)
            warnings.append(
                "pinned this checkout to %r (the former active_spec). This "
                "checkout runs %d workstreams; SPQ expects one clone per "
                "workstream (design §5), so run this migration in each clone "
                "and re-pin with SYNAPTORY_WORKSTREAM or hydrate_cycle."
                % (primary_ws, len(result_workstreams))
            )
        else:
            warnings.append(
                "no workstream pinned: the state named no active_spec. Set "
                "SYNAPTORY_WORKSTREAM or pass --workstream to hydrate_cycle."
            )

        current = spq_paths.read_index(str(project_dir)).get("current_cycle_id")
        pointer: Dict[str, Any] = {
            "version": "2.0",
            "build_mode": "spq",
            "spq": {
                "cycle_id": current,
                "cycle_seq": spq_paths.seq_of(current) if current else None,
                "workstream_id": spq_paths.read_pin(str(project_dir)),
            },
            "migrated_from_multispec": True,
            "migrated_at": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        }
        state_store.write_json_atomic(str(state_file), pointer)

    # The move ledger is what makes a mis-routed receipt diagnosable at all.
    map_path = (
        project_dir / ".synaptory" / ".migrations" / ("%s-receipt-map.json" % stamp)
    )
    state_store.write_json_atomic(
        str(map_path),
        {"stamp": stamp, "workstreams": result_workstreams, "moves": moves},
    )

    leftovers = []
    specs_dir = orch / "specs"
    if specs_dir.is_dir():
        for entry in specs_dir.rglob("*"):
            if entry.is_file():
                leftovers.append(str(entry.relative_to(orch)))

    return {
        "status": "migrated",
        "snapshot": str(snapshot) if snapshot else None,
        "receipt_map": str(map_path),
        "workstreams": result_workstreams,
        "warnings": warnings,
        "leftover_spec_files": leftovers,
    }


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Move an SPQ project off Multi-Spec onto the native store."
    )
    parser.add_argument("--project-dir", default=".")
    parser.add_argument("--yes", action="store_true", help="skip confirmation")
    parser.add_argument("--plan", action="store_true", help="describe and exit")
    parser.add_argument("--adopt-orphan-receipts", action="store_true")
    parser.add_argument("--force-overwrite", action="store_true")
    args = parser.parse_args()

    project_dir = Path(args.project_dir).resolve()
    try:
        proposal = plan(project_dir)
    except MigrationError as exc:
        print("[migrate_spq_native] %s" % exc, file=sys.stderr)
        return 2

    if proposal["status"] in ("no_state", "already_native"):
        print("[migrate_spq_native] %s; nothing to do" % proposal["status"])
        return 0

    print("SPQ project on the retired Multi-Spec layout:")
    for entry in proposal["workstreams"]:
        print(
            "  %-24s cycle=%-4s lifecycle=%-18s units=%-3d receipts=%d"
            % (
                entry["workstream_id"],
                entry["current_cycle"],
                entry["lifecycle_state"],
                entry["work_units"],
                entry["receipts"],
            )
        )
    if args.plan:
        return 0
    if not args.yes:
        print(
            "\nThis is one-way. A snapshot is written to "
            ".synaptory/.migrations/ first.\nProceed? [y/N] ",
            end="",
        )
        if input().strip().lower() not in ("y", "yes"):
            print("aborted")
            return 1

    try:
        result = migrate(
            project_dir,
            adopt_orphan_receipts=args.adopt_orphan_receipts,
            force_overwrite=args.force_overwrite,
        )
    except MigrationError as exc:
        print("[migrate_spq_native] %s" % exc, file=sys.stderr)
        return 2

    print(json.dumps(result, indent=2))
    if result.get("snapshot"):
        print(
            "\nRollback: tar -xzf %s -C %s"
            % (result["snapshot"], project_dir / ".synaptory")
        )
    for warning in result.get("warnings") or []:
        print("warning: %s" % warning, file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
